SELECT NOW(3) observed_at, DATABASE() database_schema;
SELECT installed_rank,version,description,type,script,checksum,installed_on,execution_time,success FROM flyway_schema_history WHERE version IN ('211','212') ORDER BY installed_rank;
SELECT protocol_id,device_os,s.login_state,COUNT(*) account_count FROM account a JOIN account_state s ON s.tenant_id=a.tenant_id AND s.account_id=a.id WHERE a.deleted_at IS NULL GROUP BY protocol_id,device_os,s.login_state;
SELECT a.tenant_id,a.id account_id,a.owner_user_id,a.protocol_id,a.device_os,a.account_group_id,s.login_state,s.desired_login_state,CONCAT('***',RIGHT(a.creator_deletion_identity_phone,4)) phone_tail,SHA2(a.creator_deletion_identity_phone,256) identity_hash,(SELECT GROUP_CONCAT(c.cred_format ORDER BY c.id) FROM account_credential c WHERE c.tenant_id=a.tenant_id AND c.account_id=a.id AND c.deleted_at IS NULL) cred_formats,(SELECT COUNT(*) FROM account aa WHERE aa.creator_deletion_identity_phone=a.creator_deletion_identity_phone) identity_alias_count,d.lifecycle deletion_lifecycle FROM account a JOIN account_state s ON s.tenant_id=a.tenant_id AND s.account_id=a.id LEFT JOIN account_creator_deletion d ON d.identity_hash=SHA2(a.creator_deletion_identity_phone,256) WHERE a.deleted_at IS NULL AND s.login_state=1 ORDER BY a.tenant_id,a.protocol_id,a.id LIMIT 80;
SELECT id,tenant_code,name,status FROM tenant;
SELECT column_name,column_type FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='account_group';
SELECT id,tenant_id,status,creation_mode,is_creator_delete_after_takeover,started_at FROM pull_task ORDER BY id DESC LIMIT 6;
